// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(address logAddr) public {
        // A fresh LogFile implementation with a live fallback/receive is not needed here:
        // the difference is purely the initialization guard on SetLogFile, observable
        // through the CallLog public getter of C after the call succeeds.
        vm.assume(logAddr != address(0));

        // Drive C to the post-initialization state through its public surface.
        c.Initialized();

        bool ok;
        try c.SetLogFile(logAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference C: intitalized is true, so SetLogFile reverts and ok == false.
        // Mutant M: the guard is deleted, so SetLogFile succeeds and ok == true.
        assertTrue(!ok);
    }
}
